/* BrightAI Demo — backend AI gateway | brightai.site */
(function () {
  'use strict';

  const GEMINI_MODEL   = 'gemini-2.5-flash';
  const AI_COMPLETIONS_PATH = '/api/ai/chat/completions';
  const DEMO_META = {
    demoType: 'demo-index',
    agentType: 'demo-index',
    schemaName: 'demo_index_schema',
    sourcePage: '/demo/'
  };
  const FALLBACK_RESULT = {
    executive_summary_ar: 'تعذر تشغيل التحليل الكامل حالياً، وهذه نتيجة احتياطية آمنة تساعدك على متابعة التجربة.',
    key_insights: ['حدد الهدف التجاري أولاً.', 'ابدأ بمدخلات غير حساسة.', 'راجع المخرجات قبل استخدامها في قرار تشغيلي.'],
    risks: ['جودة المدخلات تؤثر على جودة النتيجة.', 'النتيجة تقديرية وتحتاج مراجعة بشرية.'],
    recommended_actions: ['جرّب صياغة أكثر تحديداً.', 'اختر نوع مخرجات مناسباً.', 'اطلب ديمو مخصص عند الحاجة.'],
    business_impact_ar: 'يساعد الديمو على تحويل الفكرة إلى تصور أولي قابل للمراجعة.',
    integration_readiness: ['بوابة موحدة', 'مراجعة بشرية', 'قابل للتخصيص'],
    next_action_ar: 'أعد المحاولة أو تواصل مع Bright AI لنسخة مخصصة.'
  };

  const btnRun    = document.getElementById('demo-run');
  const outEl     = document.getElementById('demo-output');
  const promptEl  = document.getElementById('demo-prompt');
  const typeEl    = document.getElementById('demo-output-type');

  if (!btnRun || !outEl || !promptEl || !typeEl) return;

  const origLabel = btnRun.innerHTML;
  let controller  = null;

  /* ─── حالات UI ─── */
  function setLoading(on) {
    btnRun.disabled = on;
    btnRun.innerHTML = on
      ? '<i class="fa-solid fa-circle-notch fa-spin"></i> جارٍ التوليد...'
      : origLabel;
    if (on) {
      outEl.innerHTML = '';
      outEl.classList.add('streaming');
      _showTypingDots();
    } else {
      outEl.classList.remove('streaming');
    }
  }

  function _showTypingDots() {
    if (outEl.querySelector('.typing-dots')) return;
    const d = document.createElement('span');
    d.className = 'typing-dots';
    d.innerHTML = '<span></span><span></span><span></span>';
    outEl.appendChild(d);
  }

  function setError(msg) {
    outEl.innerHTML = `<span class="demo-error"><i class="fa-solid fa-triangle-exclamation"></i> ${msg}</span>`;
  }

  /* ─── بناء system prompt ─── */
  function buildSystemPrompt(outputType) {
    const typeMap = {
      'ملخص تنفيذي'      : 'ملخص تنفيذي واضح ومختصر في 3-5 فقرات',
      'خطة عمل مختصرة'   : 'خطة عمل مرقّمة بخطوات قابلة للتنفيذ',
      'أسئلة وأجوبة'     : 'قائمة أسئلة وأجوبة مفيدة ذات صلة',
      'اقتراحات منتجات'  : 'قائمة اقتراحات عملية ومنتجات مقترحة'
    };
    const format = typeMap[outputType] || 'رد احترافي ومفيد';
    return `أنت مساعد الذكاء الاصطناعي لمنصة BrightAI، المنصة السعودية الرائدة في حلول الأتمتة والذكاء الاصطناعي للشركات.
قدّم ${format} باللغة العربية الفصحى الواضحة. أسلوبك: مهني، موجز، ومباشر.
راعِ السياق السعودي في أمثلتك ومصطلحاتك. لا تذكر أنك نموذج Google أو Gemini.`;
  }

  /* ─── render markdown بسيط ─── */
  function renderMarkdown(text) {
    return text
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      .replace(/^#{1,3}\s+(.+)$/gm, '<strong class="md-heading">$1</strong>')
      .replace(/^[-•]\s+(.+)$/gm, '<span class="md-li">• $1</span>')
      .replace(/^\d+\.\s+(.+)$/gm, (_, t, i) => `<span class="md-li">${_ .match(/^(\d+)/)[1]}. ${t}</span>`)
      .replace(/\n/g, '<br>');
  }

  function parseMaybeJson(value) {
    if (!value || typeof value !== 'string') return value;
    const clean = value.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
    try {
      return JSON.parse(clean);
    } catch {
      return value;
    }
  }

  function asList(value) {
    if (Array.isArray(value)) return value.filter(Boolean).map(String);
    if (typeof value === 'string' && value.trim()) return [value.trim()];
    return [];
  }

  function renderStructuredResult(raw) {
    const data = parseMaybeJson(raw) || FALLBACK_RESULT;
    if (typeof data === 'string') return renderMarkdown(data);

    const sections = [
      ['ملخص تنفيذي', asList(data.executive_summary_ar || data.executiveSummary || data.executive_summary)],
      ['رؤى رئيسية', asList(data.key_insights || data.keyInsights)],
      ['المخاطر', asList(data.risks)],
      ['الإجراءات الموصى بها', asList(data.recommended_actions || data.recommendedActions)],
      ['الأثر المتوقع', asList(data.business_impact_ar || data.businessImpact)],
      ['جاهزية التكامل', asList(data.integration_readiness || data.integrationReadiness)],
      ['الخطوة التالية', asList(data.next_action_ar || data.nextAction)]
    ].filter(([, items]) => items.length);

    if (!sections.length) return renderMarkdown(String(raw || ''));

    return sections
      .map(([title, items]) => `<strong class="md-heading">${title}</strong>${items.map((item) => `<span class="md-li">• ${item}</span>`).join('<br>')}`)
      .join('<br>');
  }

  /* ─── الطلب الرئيسي ─── */
  async function runDemo() {
    const userMsg = promptEl.value.trim();
    if (!userMsg) {
      setError('يرجى كتابة طلبك أولاً.');
      return;
    }

    if (controller) { controller.abort(); }
    controller = new AbortController();
    setLoading(true);

    const body = {
      model: GEMINI_MODEL,
      demoType: DEMO_META.demoType,
      agentType: DEMO_META.agentType,
      schemaName: DEMO_META.schemaName,
      sourcePage: DEMO_META.sourcePage,
      messages: [
        { role: 'system', content: buildSystemPrompt(typeEl.value) },
        { role: 'user', content: userMsg }
      ],
      temperature: 0.7,
      max_tokens: 1024,
      response_format: {
        type: 'json_schema',
        json_schema: { name: DEMO_META.schemaName }
      }
    };

    let accumulated = '';

    try {
      const request = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: controller.signal
      };
      const res = window.BrightAIGateway?.apiFetch
        ? await window.BrightAIGateway.apiFetch(AI_COMPLETIONS_PATH, request, 45000)
        : await fetch(window.BrightAIRuntimeConfig?.buildApiUrl ? window.BrightAIRuntimeConfig.buildApiUrl(AI_COMPLETIONS_PATH) : AI_COMPLETIONS_PATH, request);

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        const errMsg  = errData?.error?.message || `خطأ ${res.status}`;
        throw new Error(errMsg);
      }

      const data = await res.json();
      accumulated = data?.data || data?.choices?.[0]?.message?.content || data?.answer || '';
      outEl.innerHTML = renderStructuredResult(accumulated);
      outEl.scrollTop = outEl.scrollHeight;

      if (!accumulated) {
        setError('لم تُسترجع أي نتيجة. جرّب مرة أخرى.');
      } else {
        // تأثير اكتمال ناجح
        outEl.classList.add('done-pulse');
        setTimeout(() => outEl.classList.remove('done-pulse'), 800);
      }

    } catch (err) {
      if (err.name === 'AbortError') return;
      console.error('[BrightAI Demo]', err);
      outEl.innerHTML = renderStructuredResult(FALLBACK_RESULT);
      outEl.classList.add('done-pulse');
    } finally {
      setLoading(false);
      controller = null;
    }
  }

  /* ─── أحداث ─── */
  btnRun.addEventListener('click', runDemo);

  // تشغيل بـ Ctrl+Enter داخل textarea
  promptEl.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      runDemo();
    }
  });

  // عداد الكلمات
  promptEl.addEventListener('input', () => {
    const counter = document.getElementById('prompt-char-count');
    if (counter) counter.textContent = `${promptEl.value.length} / 500`;
  });

})();
